/**
 * Offline stand-in for Gemini Translation Notebook:
 * apply ONLY terms found in notebook knowledge docs (00–07), never pack soft terms.
 * If the SLIM pack already contains the probe mapping, the test is INVALID.
 */

const TERM_LINE =
  /^[-*•]?\s*(.+?)\s*(?:→|->|=>)\s*(.+?)(?:\s*[（(]\s*[A-Za-z_/]+\s*[）)])?\s*$/;

export const GROUNDING_PROBE = {
  characterSource: '紫洛安',
  characterVi: 'Tử Lạc An',
  itemSource: '玄星玉',
  itemVi: 'Huyền Tinh Ngọc',
  itemViUpdated: 'Huyền Tinh Thạch',
} as const;

export class NotebookGroundingTestInvalidError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'NotebookGroundingTestInvalidError';
  }
}

export function assertSlimPackDoesNotContainMapping(
  packPrompt: string,
  source: string,
  expectedVi: string,
): void {
  const hay = packPrompt.replace(/\s+/g, ' ');
  const arrowForms = [
    `${source} → ${expectedVi}`,
    `${source}->${expectedVi}`,
    `${source} => ${expectedVi}`,
  ];
  for (const form of arrowForms) {
    if (hay.includes(form.replace(/\s+/g, ' '))) {
      throw new NotebookGroundingTestInvalidError(
        `TEST INVALID: SLIM pack contains mapping "${form}" — cannot prove Notebook contributed.`,
      );
    }
  }
  // Also reject source+target adjacent in Active Overrides section
  if (
    /## Active Overrides[\s\S]*?## Source/.test(packPrompt) &&
    packPrompt.includes(source) &&
    packPrompt.includes(expectedVi)
  ) {
    const overrides = packPrompt.split('## Source')[0] ?? '';
    if (overrides.includes(source) && overrides.includes(expectedVi)) {
      throw new NotebookGroundingTestInvalidError(
        `TEST INVALID: SLIM Active Overrides leak "${source}" / "${expectedVi}".`,
      );
    }
  }
}

/** Parse term mappings from Notebook knowledge markdown (02 + character headers). */
export function extractNotebookTermMap(
  knowledgeDocs: Record<string, string>,
): Map<string, string> {
  const map = new Map<string, string>();

  const termsMd =
    knowledgeDocs['02_PROJECT_TERMS.md'] ??
    knowledgeDocs.project_terms ??
    '';
  for (const line of termsMd.split(/\r?\n/)) {
    const t = line.trim().replace(/^[-*•]\s*/, '');
    const m = TERM_LINE.exec(t);
    if (!m) continue;
    const source = (m[1] ?? '').trim();
    const preferred = (m[2] ?? '').trim();
    if (source && preferred) map.set(source, preferred);
  }

  const charsMd =
    knowledgeDocs['03_CHARACTERS.md'] ?? knowledgeDocs.characters ?? '';
  const sections = charsMd.split(/\n(?=##\s+)/);
  for (const section of sections) {
    const header = /^##\s+(.+)\s*$/m.exec(section);
    if (!header) continue;
    const source = header[1].trim();
    const vi =
      /(?:Tên\s*Việt|preferred|translated)\s*:\s*(.+)\s*$/im.exec(section)?.[1]?.trim() ??
      null;
    if (source && vi) map.set(source, vi);
  }

  return map;
}

/**
 * Simulate Translation Notebook reply: substitute notebook terms into source.
 * Does not read pack Active Overrides — only knowledge docs.
 */
export function translateUsingNotebookKnowledge(input: {
  sourceParagraph: string;
  notebookKnowledgeDocs: Record<string, string>;
  packPrompt: string;
  probeSource: string;
  probeExpectedVi: string;
}): string {
  assertSlimPackDoesNotContainMapping(
    input.packPrompt,
    input.probeSource,
    input.probeExpectedVi,
  );

  const map = extractNotebookTermMap(input.notebookKnowledgeDocs);
  const expected = map.get(input.probeSource);
  if (expected !== input.probeExpectedVi) {
    throw new Error(
      `Notebook knowledge missing expected mapping: ${input.probeSource} → ${input.probeExpectedVi} (got ${expected ?? 'none'})`,
    );
  }

  const sources = [...map.keys()].sort((a, b) => b.length - a.length);
  let out = input.sourceParagraph;
  for (const source of sources) {
    const vi = map.get(source)!;
    out = out.split(source).join(vi);
  }
  return out;
}

/**
 * FULL-novel Notebook grounding E2E (offline harness).
 *
 * Flow: corpus → Research preprocess import → SQLite → 00–07 → Drive live
 * → version probe → SLIM pack (must NOT contain probe mapping) → Notebook
 * grounded translate must use expected VI.
 *
 * Live Gemini is simulated by notebook-grounded-translate helper that ONLY
 * reads Notebook knowledge docs — if mapping is in the pack, test is INVALID.
 */

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { DatabaseManager } from '@main/db/database-manager';
import { pathsService } from '@main/services/paths-service';
import { FullNovelPreprocessService } from '@main/bootstrap/full-novel-preprocess-service';
import { NotebookSyncService } from '@main/notebook/notebook-sync-service';
import { NotebookKnowledgeBuilder } from '@main/notebook/knowledge-builder';
import { runKnowledgeVersionProbe } from '@main/notebook/notebook-version-probe';
import { resolveTranslationPackMode } from '@main/prompt/pack-mode-resolver';
import { buildTranslationPack } from '@main/prompt/translation-pack-builder';
import { buildMemoryContext } from '@main/memory/context-selector';
import { applyTermDelta } from '@main/learning/term-delta-processor';
import { resetNotebookSyncService } from '@main/notebook/notebook-sync-service-singleton';
import { toCharacterDto, toRelationshipDto } from '@main/services/memory-dto';
import { KNOWLEDGE_FILE_NAMES, KNOWLEDGE_TYPES } from '@shared/constants/knowledge';
import {
  GROUNDING_PROBE,
  translateUsingNotebookKnowledge,
} from './helpers/notebook-grounded-translate';

const FIXTURE_DIR = path.resolve(
  __dirname,
  '../fixtures/full-novel-grounding',
);

function loadFixture(name: string): string {
  return fs.readFileSync(path.join(FIXTURE_DIR, name), 'utf8');
}

function seedBindings(db: DatabaseManager, projectId: string, notebookId: string): void {
  for (const type of KNOWLEDGE_TYPES) {
    db.notebookSourceBindings.upsert({
      projectId,
      notebookId,
      knowledgeType: type,
      sourceName: KNOWLEDGE_FILE_NAMES[type],
      bindingType: 'DRIVE_LIVE',
      status: 'active',
      driveFileId: `drive-${type}`,
    });
  }
}

describe('FULL-novel Notebook grounding E2E', () => {
  let db: DatabaseManager;
  let tmp: string;
  let projectId: string;
  let accountId: string;
  let chapterId: string;

  beforeEach(() => {
    tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'nt-grounding-e2e-'));
    pathsService.initializeAt(tmp);
    resetNotebookSyncService();
    db = new DatabaseManager({
      dataDir: pathsService.getPath('data'),
      backupsDir: pathsService.getPath('backups'),
    });

    const project = db.projects.create({
      title: 'Grounding Fixture Novel',
      source_language: 'zh',
      target_language: 'vi',
      author_name: 'E2E',
      genre: 'xianxia',
    });
    projectId = project.id;

    const account = db.googleAccounts.create({
      label: 'Grounding Worker',
      email: 'grounding@test.com',
      displayName: 'Grounding',
      profileDirName: 'profile-grounding',
      status: 'READY',
    });
    accountId = account.id;

    const novel = loadFixture('novel-ch01.txt').trim();
    const chapter = db.chapters.create({
      project_id: projectId,
      chapter_number: 1,
      sequence_order: 1,
      display_title: '第一章 紫洛安试炼',
      source_text: novel,
      source_status: 'SOURCE_READY',
    });
    chapterId = chapter.id;

    const lines = novel.split(/\n+/).filter((l) => l.trim() && !/^第.+章/.test(l.trim()));
    lines.forEach((line, i) => {
      db.paragraphs.create({
        chapter_id: chapterId,
        paragraph_id: `C000001:P${String(i + 1).padStart(6, '0')}`,
        sequence: i + 1,
        source_text: line.trim(),
      });
    });

    db.notebooks.upsert({
      project_id: projectId,
      google_account_id: accountId,
      notebook_name: '[NovelTrans] Grounding Translation',
      notebook_role: 'TRANSLATION',
      notebook_id: 'nb-grounding',
      resource_url: 'https://notebook.google.com/grounding',
      status: 'sync_pending',
      instructions_hash: 'grounding-hash',
    });
    seedBindings(db, projectId, 'nb-grounding');
  });

  afterEach(() => {
    resetNotebookSyncService();
    db.close();
    if (tmp) fs.rmSync(tmp, { recursive: true, force: true });
  });

  async function runFullImportAndVerify(): Promise<{
    sync: NotebookSyncService;
    docs: ReturnType<NotebookKnowledgeBuilder['buildAll']>;
    verifiedVersion: number;
  }> {
    const preprocess = new FullNovelPreprocessService(db);

    // 1) FULL preprocess: pack corpus + Research analysis import
    const packed = preprocess.packCorpus(projectId);
    expect(packed.parts.length).toBeGreaterThanOrEqual(1);
    const prompt = preprocess.getPrompt(projectId);
    expect(prompt.prompt).toContain('DO NOT TRANSLATE');
    expect(prompt.prompt).toContain('file:02_PROJECT_TERMS.md');

    const imported = preprocess.importResult(projectId, {
      text: loadFixture('research-response.md'),
      temporalProvenance: true,
    });
    expect(imported.foundKeys.length).toBeGreaterThanOrEqual(6);
    expect(imported.message).toMatch(/Imported/i);

    // 2) SQLite contains probe facts (candidates + character)
    const candidates = db.termCandidates.listPending(projectId);
    expect(candidates.some((c) => c.source_text === GROUNDING_PROBE.itemSource)).toBe(
      true,
    );
    expect(
      candidates.some((c) => c.source_text === GROUNDING_PROBE.characterSource),
    ).toBe(true);
    const character = db.characters.getByName(
      projectId,
      GROUNDING_PROBE.characterSource,
    );
    expect(character?.translated_name).toBe(GROUNDING_PROBE.characterVi);

    // Promote candidates → project terms (post-research confirm → structured vault)
    applyTermDelta(
      db,
      [
        {
          action: 'confirm',
          source: GROUNDING_PROBE.itemSource,
          target: GROUNDING_PROBE.itemVi,
        },
        {
          action: 'confirm',
          source: GROUNDING_PROBE.characterSource,
          target: GROUNDING_PROBE.characterVi,
        },
      ],
      { projectId, chapterNumber: 1 },
    );
    const itemTerm = db.terms.findBySource(GROUNDING_PROBE.itemSource, projectId);
    expect(itemTerm).toBeTruthy();
    expect(itemTerm!.locked).toBe(0);

    // 3) Build Translation Knowledge 00–07 (+ sync_state)
    const builder = new NotebookKnowledgeBuilder(db);
    let docs = builder.rebuildAndTrack(projectId);
    expect(docs['02_PROJECT_TERMS.md']).toContain(GROUNDING_PROBE.itemSource);
    expect(docs['02_PROJECT_TERMS.md']).toContain(GROUNDING_PROBE.itemVi);
    expect(docs['03_CHARACTERS.md']).toContain(GROUNDING_PROBE.characterSource);

    // 4) Drive LIVE sync (noop upload) → pending version
    const sync = new NotebookSyncService(db, async () => { await Promise.resolve(); return ({ uploaded: true }));; }
    await sync.syncDrive(projectId);
    const pending = db.driveSyncState.ensure(projectId);
    expect(pending.pending_knowledge_version).toBeGreaterThan(0);
    expect(pending.pending_sync_nonce).toBeTruthy();
    expect(pending.version_probe_status).toBe('pending');

    // 5) Version probe → CONTENT_CURRENT
    const probe = await runKnowledgeVersionProbe(db, {
      projectId,
      accountId,
      capture: async () =>
        `NT_VERSION=${pending.pending_knowledge_version}\nNT_NONCE=${pending.pending_sync_nonce}`,
    });
    expect(probe.status).toBe('verified');
    expect(probe.reason).toBe('NOTEBOOK_VERSION_VERIFIED');

    const health = sync.getHealth(projectId, accountId);
    expect(health.knowledgeVerified).toBe(true);
    expect(health.status).toBe('ready');
    expect(health.usableForSlimPack).toBe(true);

    docs = builder.buildAll(projectId);
    return {
      sync,
      docs,
      verifiedVersion: pending.pending_knowledge_version,
    };
  }

  function buildSlimPackPrompt(): string {
    const mode = resolveTranslationPackMode(db, {
      projectId,
      accountId,
      providerType: 'PLAYWRIGHT_GEMINI',
    });
    expect(mode.packMode).toBe('slim');
    expect(mode.reason).toBe('ready_verified');

    const context = buildMemoryContext(
      db,
      { projectId, chapterIds: [chapterId] },
      (characterId) => {
        const row = db.characters.getById(characterId);
        if (!row) return null;
        return toCharacterDto(
          row,
          db.characters.listAliases(row.id).map((a) => a.alias),
        );
      },
      (rel) => {
        const from = db.characters.getById(rel.from_character_id);
        const to = db.characters.getById(rel.to_character_id);
        return toRelationshipDto(
          rel,
          from?.canonical_name ?? rel.from_character_id,
          to?.canonical_name ?? rel.to_character_id,
        );
      },
    );

    // Soft match may see 玄星玉 in batch — must NOT enter SLIM overrides.
    expect(
      context.activeTerms.some((t) => t.sourceText === GROUNDING_PROBE.itemSource),
    ).toBe(true);

    const pack = buildTranslationPack(db, {
      projectId,
      chapterIds: [chapterId],
      style: 'balanced',
      context,
      packMode: 'slim',
    });
    return pack.prompt;
  }

  it('FULL flow: Research → SQLite → version verify → SLIM without mapping → Notebook term', async () => {
    const { docs } = await runFullImportAndVerify();

    const packPrompt = buildSlimPackPrompt();
    expect(packPrompt).toContain(GROUNDING_PROBE.itemSource); // in Source only
    expect(packPrompt).not.toMatch(
      new RegExp(`${GROUNDING_PROBE.itemSource}\\s*(→|->|=>)\\s*${GROUNDING_PROBE.itemVi}`),
    );

    const sourceLine =
      db.paragraphs
        .listByChapter(chapterId)
        .find((p) => p.source_text.includes(GROUNDING_PROBE.itemSource))?.source_text ??
      '';
    expect(sourceLine).toContain(GROUNDING_PROBE.itemSource);

    const knowledgeDocs: Record<string, string> = {
      '02_PROJECT_TERMS.md': docs['02_PROJECT_TERMS.md'],
      '03_CHARACTERS.md': docs['03_CHARACTERS.md'],
    };

    const translated = translateUsingNotebookKnowledge({
      sourceParagraph: sourceLine,
      notebookKnowledgeDocs: knowledgeDocs,
      packPrompt,
      probeSource: GROUNDING_PROBE.itemSource,
      probeExpectedVi: GROUNDING_PROBE.itemVi,
    });

    expect(translated).toContain(GROUNDING_PROBE.itemVi);
    expect(translated).not.toContain(GROUNDING_PROBE.itemSource);
  }, 60_000);

  it('UPDATE: term rename bumps version; new Notebook mapping used; pack still clean', async () => {
    await runFullImportAndVerify();

    // User renames item translation
    applyTermDelta(
      db,
      [
        {
          action: 'confirm',
          source: GROUNDING_PROBE.itemSource,
          target: GROUNDING_PROBE.itemViUpdated,
        },
      ],
      { projectId, chapterNumber: 1 },
    );
    // Ensure preferred translation row updated
    const term = db.terms.findBySource(GROUNDING_PROBE.itemSource, projectId)!;
    db.terms.setTranslations(term.id, GROUNDING_PROBE.itemViUpdated, []);

    const sync = new NotebookSyncService(db, async () => { await Promise.resolve(); return ({ uploaded: true }));; }
    sync.markDirty(projectId, 'TERM_CHANGED');
    const builder = new NotebookKnowledgeBuilder(db);
    let docs = builder.rebuildAndTrack(projectId);
    expect(docs['02_PROJECT_TERMS.md']).toContain(GROUNDING_PROBE.itemViUpdated);

    await sync.syncDrive(projectId);
    const pending = db.driveSyncState.ensure(projectId);
    const probe = await runKnowledgeVersionProbe(db, {
      projectId,
      accountId,
      capture: async () =>
        `NT_VERSION=${pending.pending_knowledge_version}\nNT_NONCE=${pending.pending_sync_nonce}`,
    });
    expect(probe.status).toBe('verified');
    expect(pending.pending_knowledge_version).toBeGreaterThan(1);

    docs = builder.buildAll(projectId);
    const packPrompt = buildSlimPackPrompt();

    const sourceLine =
      db.paragraphs
        .listByChapter(chapterId)
        .find((p) => p.source_text.includes(GROUNDING_PROBE.itemSource))?.source_text ??
      '';

    const translated = translateUsingNotebookKnowledge({
      sourceParagraph: sourceLine,
      notebookKnowledgeDocs: {
        '02_PROJECT_TERMS.md': docs['02_PROJECT_TERMS.md'],
        '03_CHARACTERS.md': docs['03_CHARACTERS.md'],
      },
      packPrompt,
      probeSource: GROUNDING_PROBE.itemSource,
      probeExpectedVi: GROUNDING_PROBE.itemViUpdated,
    });

    expect(translated).toContain(GROUNDING_PROBE.itemViUpdated);
    expect(translated).not.toContain(GROUNDING_PROBE.itemVi);
  }, 60_000);
});

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import {
  createDatabaseManager,
  closeDatabase,
  type DatabaseManager,
} from '@main/db/connection';
import { resolveAppPaths, pathsService } from '@main/services/paths-service';
import { AccountWorkerService } from '@main/services/account-worker-service';
import { AuditLogService } from '@main/security/audit-log-service';
import { SecretStorageService } from '@main/security/secret-storage-service';
import type { SafeStorageBackend } from '@main/security/safe-storage-backend';
import { BrowserProfileManager } from '@main/automation/browser-runner/profile-manager';
import { ProfileLeaseLockManager } from '@main/automation/browser-runner/profile-lock';
import type {
  BrowserSessionController,
  BrowserSessionHandle,
  SessionProbeResult,
} from '@main/automation/browser-runner/browser-session-controller';

function createXorBackend(): SafeStorageBackend {
  return {
    isAvailable: () => Promise.resolve(true),
    encrypt(plainText: string) {
      return Promise.resolve({ ciphertext: Buffer.from(`x:${plainText}`, 'utf8') });
    },
    decrypt(encrypted: Buffer) {
      return Promise.resolve({
        plaintext: encrypted.toString('utf8').replace(/^x:/, ''),
        shouldReEncrypt: false,
      });
    },
    getBackendName: () => 'test',
  };
}

function createMockBrowser(probe: SessionProbeResult): BrowserSessionController {
  return {
    open(options) {
      const handle: BrowserSessionHandle = {
        profilePath: options.profilePath,
        close: () => Promise.resolve(),
        probeSession: () => Promise.resolve(probe),
        extractGeminiCookies: () =>
          Promise.resolve({
            secure1psid: 'mock-psid',
            secure1psidts: 'mock-psidts',
          }),
        isOpen: () => true,
        focus: () => Promise.resolve(),
      };
      return Promise.resolve(handle);
    },
  };
}

describe('AccountWorkerService', () => {
  let tempRoot: string;
  let dataDir: string;
  let backupsDir: string;
  let db: DatabaseManager;
  let service: AccountWorkerService;
  let profiles: BrowserProfileManager;
  let locks: ProfileLeaseLockManager;

  beforeEach(() => {
    tempRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'noveltrans-acct-'));
    pathsService.initializeAt(tempRoot);
    const paths = resolveAppPaths(tempRoot);
    dataDir = paths.data;
    backupsDir = paths.backups;
    fs.mkdirSync(dataDir, { recursive: true });
    fs.mkdirSync(backupsDir, { recursive: true });
    fs.mkdirSync(paths.browserProfiles, { recursive: true });
    closeDatabase();

    db = createDatabaseManager({ dataDir, backupsDir });
    profiles = new BrowserProfileManager();
    locks = new ProfileLeaseLockManager();
    service = new AccountWorkerService({
      accounts: db.googleAccounts,
      auditLog: new AuditLogService(db.auditLog, db.appMeta),
      secretStorage: new SecretStorageService({
        backend: createXorBackend(),
        repository: db.secrets,
      }),
      profiles,
      locks,
      browser: createMockBrowser({
        usable: true,
        email: 'user@example.com',
        displayName: 'user@example.com',
      }),
    });
  });

  afterEach(() => {
    db.close();
    closeDatabase();
    fs.rmSync(tempRoot, { recursive: true, force: true });
  });

  it('creates account with isolated profile path and persists', async () => {
    const account = await service.addAccount({
      label: 'Work',
      skipBrowser: true,
    });

    expect(account.id).toMatch(
      /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i,
    );
    expect(account.profile_dir_name).toBe(account.id);
    expect(account.status).toBe('LOGIN_REQUIRED');
    expect(profiles.profileExists(account.profile_dir_name)).toBe(true);

    const pathA = profiles.resolveProfilePath(account.profile_dir_name);
    const second = await service.addAccount({ label: 'Personal', skipBrowser: true });
    const pathB = profiles.resolveProfilePath(second.profile_dir_name);
    expect(pathA).not.toBe(pathB);

    db.close();
    const reopened = createDatabaseManager({ dataDir, backupsDir });
    try {
      const reloaded = reopened.googleAccounts.getById(account.id);
      expect(reloaded?.label).toBe('Work');
    } finally {
      reopened.close();
    }
    db = createDatabaseManager({ dataDir, backupsDir });
    service = new AccountWorkerService({
      accounts: db.googleAccounts,
      auditLog: new AuditLogService(db.auditLog, db.appMeta),
      secretStorage: new SecretStorageService({
        backend: createXorBackend(),
        repository: db.secrets,
      }),
      profiles,
      locks,
      browser: createMockBrowser({
        usable: true,
        email: 'user@example.com',
        displayName: 'user@example.com',
      }),
    });
  });

  it('disables worker and requires confirm for delete', async () => {
    const account = await service.addAccount({ label: 'Temp', skipBrowser: true });
    const disabled = service.disableWorker(account.id);
    expect(disabled.status).toBe('DISABLED');
    expect(disabled.worker_enabled).toBe(false);

    await expect(service.removeAccount(account.id, false)).rejects.toThrow(
      /confirmation required/i,
    );

    await service.removeAccount(account.id, true);
    expect(service.getAccount(account.id)).toBeNull();
    expect(profiles.profileExists(account.id)).toBe(false);
  });

  it('enforces profile path isolation lock', async () => {
    const account = await service.addAccount({ label: 'Lock', skipBrowser: true });
    const profilePath = profiles.resolveProfilePath(account.profile_dir_name);

    locks.acquire(profilePath, account.id);
    expect(locks.isLocked(profilePath)).toBe(true);
    expect(() => {
      locks.acquire(profilePath, 'other-worker');
    }).toThrow(/PROFILE_BUSY|already in use|đang được sử dụng/i);

    locks.release(profilePath, account.id);
    expect(locks.isLocked(profilePath)).toBe(false);
  });

  it('completes login with detected email and sets READY', async () => {
    const account = await service.addAccount({ label: 'Login', skipBrowser: true });
    const ready = await service.completeLogin(account.id);
    expect(ready.status).toBe('READY');
    expect(ready.email).toBe('user@example.com');
  });

  it('trusts fallback email when probe says not usable', async () => {
    service = new AccountWorkerService({
      accounts: db.googleAccounts,
      auditLog: new AuditLogService(db.auditLog, db.appMeta),
      secretStorage: new SecretStorageService({
        backend: createXorBackend(),
        repository: db.secrets,
      }),
      profiles,
      locks,
      browser: createMockBrowser({
        usable: false,
        email: null,
        displayName: null,
        reason: 'LOGIN_REQUIRED',
      }),
    });
    const account = await service.addAccount({ label: 'Manual', skipBrowser: true });
    const ready = await service.completeLogin(account.id, { email: 'manual@example.com' });
    expect(ready.status).toBe('READY');
    expect(ready.email).toBe('manual@example.com');
  });

  it('throws when probe fails and no fallback email', async () => {
    service = new AccountWorkerService({
      accounts: db.googleAccounts,
      auditLog: new AuditLogService(db.auditLog, db.appMeta),
      secretStorage: new SecretStorageService({
        backend: createXorBackend(),
        repository: db.secrets,
      }),
      profiles,
      locks,
      browser: createMockBrowser({
        usable: false,
        email: null,
        displayName: null,
        reason: 'LOGIN_REQUIRED',
      }),
    });
    const account = await service.addAccount({ label: 'Fail', skipBrowser: true });
