        await prepareNotebook({
          projectId: 'project-1',
          notebookUrl: 'https://notebook.google.com/n/p1',
          openNotebook: async (_p, url) => { await Promise.resolve(); return {; }
            opens.push(url);
          },
          verifyReady: async () => { await Promise.resolve(); return {; }
            verifies.push('p1');
          },
        });
      },
    );

    await manager.runExclusive(
      {
        accountId: 'account-a',
        profilePath: profileA,
        diagnosticsDir: path.join(tempRoot, 'diag-a'),
      },
      async ({ prepareNotebook }) => {
        await prepareNotebook({
          projectId: 'project-2',
          notebookUrl: 'https://notebook.google.com/n/p2',
          openNotebook: async (_p, url) => { await Promise.resolve(); return {; }
            opens.push(url);
          },
          verifyReady: async () => { await Promise.resolve(); return {; }
            verifies.push('p2');
          },
        });
      },
    );

    expect(launchCalls).toBe(1);
    expect(opens).toEqual([
      'https://notebook.google.com/n/p1',
      'https://notebook.google.com/n/p2',
    ]);
    expect(verifies).toEqual(['p1']);
  });

  it('recovers when page crashes by opening a new page', async () => {
    let firstPage: Page | null = null;
    await manager.runExclusive(
      {
        accountId: 'account-a',
        profilePath: profileA,
        diagnosticsDir: path.join(tempRoot, 'diag-a'),
      },
      async ({ prepareNotebook }) => {
        firstPage = await prepareNotebook({
          projectId: 'project-1',
          notebookUrl: 'https://notebook.google.com/n/p1',
          openNotebook: () => Promise.resolve(),
        });
        (firstPage as unknown as { isClosed: () => boolean }).isClosed = () => true;
      },
    );

    await manager.runExclusive(
      {
        accountId: 'account-a',
        profilePath: profileA,
        diagnosticsDir: path.join(tempRoot, 'diag-a'),
      },
      async ({ runtime, prepareNotebook }) => {
        const page = await prepareNotebook({
          projectId: 'project-1',
          notebookUrl: 'https://notebook.google.com/n/p1',
          openNotebook: () => Promise.resolve(),
        });
        expect(page).not.toBe(firstPage);
        expect(runtime.getContext()?.newPage).toHaveBeenCalled();
      },
    );
  });

  it('serializes concurrent ops on same account', async () => {
    const order: string[] = [];
    const a = manager.runExclusive(
      {
        accountId: 'account-a',
        profilePath: profileA,
        diagnosticsDir: path.join(tempRoot, 'diag-a'),
      },
      async () => {
        order.push('a-start');
        await new Promise((r) => setTimeout(r, 40));
        order.push('a-end');
      },
    );
    const b = manager.runExclusive(
      {
        accountId: 'account-a',
        profilePath: profileA,
        diagnosticsDir: path.join(tempRoot, 'diag-a'),
      },
      async () => { await Promise.resolve(); return {; }
        order.push('b-start');
        order.push('b-end');
      },
    );
    await Promise.all([a, b]);
    expect(order).toEqual(['a-start', 'a-end', 'b-start', 'b-end']);
    expect(launchCalls).toBe(1);
  });

  it('marks NEEDS_ATTENTION on session expired', async () => {
    await expect(
      manager.runExclusive(
        {
          accountId: 'account-a',
          profilePath: profileA,
          diagnosticsDir: path.join(tempRoot, 'diag-a'),
        },
        async () => { await Promise.resolve(); return {; }
          throw new AutomationError('SESSION_EXPIRED', 'session gone');
        },
      ),
    ).rejects.toMatchObject({ code: 'SESSION_EXPIRED' });

    expect(manager.getRuntime('account-a')?.health).toBe('NEEDS_ATTENTION');
  });

  it('shutdown closes all runtimes cleanly', async () => {
    await manager.runExclusive(
      {
        accountId: 'account-a',
        profilePath: profileA,
        diagnosticsDir: path.join(tempRoot, 'diag-a'),
      },
      async ({ prepareNotebook }) => {
        await prepareNotebook({
          projectId: 'p1',
          notebookUrl: 'https://notebook.google.com/n/p1',
          openNotebook: () => Promise.resolve(),
        });
      },
    );
    await manager.shutdownAll();
    expect(manager.getRuntime('account-a')).toBeUndefined();
    expect(profileLockManager.isLocked(profileA)).toBe(false);
    expect(events.some((e) => e.event === 'BROWSER_RUNTIME_CLOSED')).toBe(true);
  });

  it('refuses second launch on same profile while runtime open', async () => {
    await manager.runExclusive(
      {
        accountId: 'account-a',
        profilePath: profileA,
        diagnosticsDir: path.join(tempRoot, 'diag-a'),
      },
      async ({ prepareNotebook }) => {
        await prepareNotebook({
          projectId: 'p1',
          notebookUrl: 'https://notebook.google.com/n/p1',
          openNotebook: () => Promise.resolve(),
        });
      },
    );
    expect(profileLockManager.isHeldByRuntime(profileA, 'account-a')).toBe(true);

    await expect(
      manager.runExclusive(
        {
          accountId: 'account-other',
          profilePath: profileA,
          diagnosticsDir: path.join(tempRoot, 'diag-x'),
        },
        async () => { await Promise.resolve(); return 'nope'; },
      ),
    ).rejects.toThrow(/already in use/i);
  });
});

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { describe, it, expect, beforeAll, afterAll, beforeEach, afterEach } from 'vitest';
import { AutomationManager } from '@main/automation/automation-manager';
import { ProfileLockManager } from '@main/automation/browser-runner/profile-lock';
import { newId } from '@main/db/utils/uuid';
import { startFixtureServer } from './fixture-server';

const FIXTURE_DIR = path.resolve(
  __dirname,
  '../../fixtures/automation',
);

describe('Browser automation core (mock HTML)', () => {
  let baseUrl: string;
  let closeServer: () => Promise<void>;
  let tempRoot: string;
  let manager: AutomationManager;
  let locks: ProfileLockManager;

  beforeAll(async () => {
    const server = await startFixtureServer(FIXTURE_DIR);
    baseUrl = server.baseUrl;
    closeServer = server.close;
  });

  afterAll(async () => {
    await closeServer();
  });

  beforeEach(() => {
    tempRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'nts-auto-'));
    locks = new ProfileLockManager();
    manager = new AutomationManager({
      cacheDir: path.join(tempRoot, 'cache'),
      transport: 'in-process',
      locks,
    });
  });

  afterEach(async () => {
    await manager.disposeAll();
    fs.rmSync(tempRoot, { recursive: true, force: true });
  });

  it('runs OPEN / NAVIGATE / GET_STATUS / SCREENSHOT / CLOSE commands', async () => {
    const workerId = newId();
    const profilePath = path.join(tempRoot, 'profiles', workerId);

    const opened = await manager.openWorker({
      workerId,
      profilePath,
      headless: true,
      startUrl: `${baseUrl}/ready.html`,
    });
    expect(opened.ok).toBe(true);
    expect(opened.state).toBe('READY');

    const status = await manager.sendCommand(workerId, {
      id: newId(),
      type: 'GET_STATUS',
    });
    expect(status.data?.url).toContain('ready.html');

    const shot = await manager.sendCommand(workerId, {
      id: newId(),
      type: 'SCREENSHOT',
      tag: 'ready',
    });
    expect(shot.ok).toBe(true);
    const shotPath = shot.data?.screenshotPath;
    expect(typeof shotPath).toBe('string');
    expect(fs.existsSync(String(shotPath))).toBe(true);

    const closed = await manager.sendCommand(workerId, {
      id: newId(),
      type: 'CLOSE',
    });
    expect(closed.state).toBe('STOPPED');
  });

  it('persists profile data across reopen', async () => {
    const workerId = newId();
    const profilePath = path.join(tempRoot, 'profiles', workerId);

    await manager.openWorker({
      workerId,
      profilePath,
      headless: true,
      startUrl: `${baseUrl}/ready.html`,
    });
    await manager.closeWorker(workerId);

    const reopened = await manager.openWorker({
      workerId,
      profilePath,
      headless: true,
      startUrl: `${baseUrl}/ready.html`,
    });
    expect(reopened.ok).toBe(true);

    // localStorage from first visit should still be present (Playwright persistent context)
    const nav = await manager.sendCommand(workerId, {
      id: newId(),
      type: 'NAVIGATE',
      url: `${baseUrl}/ready.html`,
    });
    expect(nav.ok).toBe(true);
    expect(fs.existsSync(profilePath)).toBe(true);
  });

  it('returns LOGIN_REQUIRED without infinite retry', async () => {
    const workerId = newId();
    const profilePath = path.join(tempRoot, 'profiles', workerId);
    await manager.openWorker({
      workerId,
      profilePath,
      headless: true,
      startUrl: `${baseUrl}/ready.html`,
    });

    const result = await manager.sendCommand(workerId, {
      id: newId(),
      type: 'NAVIGATE',
      url: `${baseUrl}/login.html`,
    });

    expect(result.ok).toBe(false);
    expect(result.errorCode).toBe('LOGIN_REQUIRED');
    expect(result.state).toBe('USER_ACTION_REQUIRED');
  });

  it('captures screenshot on navigation timeout failure', async () => {
    const workerId = newId();
    const profilePath = path.join(tempRoot, 'profiles', workerId);
    await manager.openWorker({
      workerId,
      profilePath,
      headless: true,
      startUrl: `${baseUrl}/ready.html`,
    });

    const result = await manager.sendCommand(workerId, {
      id: newId(),
      type: 'NAVIGATE',
      url: 'http://127.0.0.1:1/',
      timeoutMs: 500,
    });

    expect(result.ok).toBe(false);
    expect(
      result.errorCode === 'NAVIGATION_TIMEOUT' ||
        result.errorCode === 'NETWORK_ERROR',
    ).toBe(true);
    expect(result.diagnostics?.operationName).toBeTruthy();
    expect(result.diagnostics?.timestamp).toBeTruthy();
    // screenshot may or may not succeed depending on browser state; path field must exist
    expect(result.diagnostics).toBeDefined();
    expect('screenshotPath' in (result.diagnostics ?? {})).toBe(true);
  });

  it('RESTART reopens dedicated profile without Chrome default profile', async () => {
    const workerId = newId();
    const profilePath = path.join(tempRoot, 'profiles', workerId);
    await manager.openWorker({
      workerId,
      profilePath,
      headless: true,
      startUrl: `${baseUrl}/ready.html`,
    });

    const restarted = await manager.sendCommand(workerId, {
      id: newId(),
      type: 'RESTART',
      startUrl: `${baseUrl}/ready.html`,
    });
    expect(restarted.ok).toBe(true);
    expect(restarted.data?.profilePath).toBe(path.resolve(profilePath));
  });

  it('never allows two workers on same userDataDir', async () => {
    const profilePath = path.join(tempRoot, 'profiles', 'shared');
    const a = newId();
    await manager.openWorker({
      workerId: a,
      profilePath,
      headless: true,
      startUrl: `${baseUrl}/ready.html`,
    });

    await expect(
      manager.openWorker({
        workerId: newId(),
        profilePath,
        headless: true,
      }),
    ).rejects.toThrow(/already in use|lock/i);
  });
});

