    expect(result.critical).toBe(false);
    expect(result.driveSyncTriggered).toBe(false);
    expect(syncDrive).not.toHaveBeenCalled();
    expect(db.driveSyncState.ensure(projectId).chapters_since_sync).toBe(1);
  });
});

